        await GetOrCreateModule(new TrainingModule
        {
            Title = "Standard Costing and Overhead",
            Slug = "costing-overview",
            Summary = "How Forge turns rent, utilities, payroll taxes and benefits into an overhead rate per labor hour, and the two ways to switch it on",
