            ContentJson = """{"title":"Costing Field Reference","groups":[{"heading":"Periods tab","items":[{"label":"Start / End","value":"The date range the period covers. The quick start makes a calendar-year period; by hand you can choose any range."},{"label":"Status","value":"Open until you freeze it. Frozen periods have their rates locked."},{"label":"Freeze","value":"Turns every pool budget in the period into a rate and builds a rate card per work center. Only shown while the period is Open."},{"label":"View Rates","value":"Shows the frozen rate card: Labor, Labor OH, Machine, Mch OH Var and Mch OH Fixed per work center. Switch between table and chart with the view toggle."}]},{"heading":"Cost Centers tab","items":[{"label":"Code / Name","value":"Short code and display name, for example PLANT / Plant."},{"label":"Type","value":"Production, Support, SG&A or Warehouse."},{"label":"Sq Ft","value":"Floor area, for spreading facility costs. Optional."},{"label":"Headcount","value":"People in the cost center. Optional; the quick start fills it from your direct headcount."},{"label":"Inventoriable","value":"On means the cost center's overhead belongs in product cost. Leave it off for office and selling costs."}]},{"heading":"Overhead Pools tab","items":[{"label":"Cost Center","value":"The cost center the pool belongs to."},{"label":"Code / Name","value":"Short code and display name, for example UTIL / Utilities."},{"label":"Behavior","value":"Fixed (rent), Variable (power), or Semi-variable (part fixed, part varies with volume)."},{"label":"Fixed Portion","value":"For Semi-variable pools: the share that does not move with volume."},{"label":"Driver","value":"What spreads the pool across parts: Machine hour, Labor hour, Labor dollar, Material dollar, Unit or Receipt count."}]},{"heading":"Set Pool Budget","items":[{"label":"Pool","value":"Which pool the budget is for."},{"label":"Period","value":"Which period it applies to."},{"label":"Budget Amount","value":"Dollars expected in the pool for the whole period."},{"label":"Driver Qty","value":"Expected driver quantity for the period (hours, dollars or units). Rate = Budget Amount divided by Driver Qty."}]},{"heading":"Quick start dialog","items":[{"label":"Template","value":"Which set of questions to ask. Defaults to the system template."},{"label":"Fiscal year","value":"The calendar year the period and budgets are created for."},{"label":"Direct headcount","value":"Number of direct-labor people. Multiplied by 2,080 hours to size the budgets."},{"label":"Average hourly wage","value":"Typical direct wage. Used for percent-of-wages lines and default labor rates."},{"label":"Template lines","value":"One amount per line: per month, per year, per employee per month, or percent of wages, as labeled."},{"label":"Also create GL expense accounts + budget lines","value":"With the full general ledger on, mirrors each line into an expense account and a budget line."},{"label":"Set default labor rates for users without one","value":"Gives each active user with no labor rate a standard rate of wage plus per-hour burden, and an overtime rate of one and a half times that."},{"label":"Apply","value":"Creates or updates everything in one step. If anything fails, nothing is changed."}]},{"heading":"Template editor","items":[{"label":"Template name / Description","value":"How the template appears in the quick start's Template list."},{"label":"Code / Category","value":"The pool code and name each line will create."},{"label":"Behavior / Driver","value":"Carried onto the pool the line creates."},{"label":"Asked as","value":"How the quick start phrases the question: Monthly amount, Annual amount, Per employee / month, or Percent of wages."},{"label":"Default","value":"Pre-filled answer. Optional."},{"label":"GL account # / name","value":"Optional. Lines with an account can be mirrored into the general ledger when the quick start's GL toggle is on."},{"label":"System","value":"The shipped template. It can be edited but not deleted."}]},{"heading":"Admin > Costing (departmental rates)","items":[{"label":"Use departmental overhead rates","value":"Off: overhead is each work center's burden rate per hour times routed hours. On: overhead is labor cost times the percentage below."},{"label":"Overhead % of labor by work center","value":"One box per active work center. Blank means that work center keeps its flat burden rate."}]}]}"""
        });

